inputs = ['ciz', 'xfz', 'befye', 'ex', 'dg']
outputs = ['cibbi', 'dgbbi', 'beege', 'ehiz', 'dg']

# First, let's manually identify all the transformations needed
transformations = []

# For each changed pair, determine what needs to be replaced
changed_pairs = [(0, 'ciz', 'cibbi'), (1, 'xfz', 'dgbbi'), (2, 'befye', 'beege'), (3, 'ex', 'ehiz')]

for idx, inp, outp in changed_pairs:
    print(f"Analyzing pair {idx}: '{inp}' -> '{outp}'")

    # Find minimal edit operations
    if len(inp) == len(outp):
        # Same length - look for character substitutions
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
                transformations.append((inp[i], outp[i]))
    else:
        # Different lengths - might involve insertion/deletion
        # Let's focus on character-by-character comparison
        min_len = min(len(inp), len(outp))
        for i in range(min_len):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
                transformations.append((inp[i], outp[i]))

        # Handle cases where lengths differ
        if len(inp) > len(outp):
            # Deletion occurred
            for i in range(min_len, len(inp)):
                print(f"  Delete position {i}: '{inp[i]}'")
                transformations.append((inp[i], ""))
        elif len(outp) > len(inp):
            # Insertion occurred  
            for i in range(min_len, len(outp)):
                print(f"  Insert position {i}: '{outp[i]}'")
                transformations.append(("", outp[i]))

print("\nAll transformations identified:")
for t in transformations:
    print(f"  {t}")

